#!/bin/sh

populate_archlinux() {
	if usr/bin/pacman-key -l >/dev/null 2>&1; then
		usr/bin/pacman-key --populate archlinux
	fi
}


post_upgrade() {
	# Older versions of pacman (before 6.1.0) disabled locking by default:
	# https://gitlab.archlinux.org/pacman/pacman/-/commit/1d1bb6fa1a8247242fbdd226f50265a278a12ac8
	#
	# This still causes lots of problems, so force to remove that option.
	if grep -qx 'lock-never' etc/pacman.d/gnupg/gpg.conf 2>/dev/null; then
		sed -i '/^lock-never$/d' etc/pacman.d/gnupg/gpg.conf
	fi

	populate_archlinux
}

post_install() {
	if [ -x usr/bin/pacman-key ]; then
		populate_archlinux
	fi
}

post_install() {
  post_upgrade $1 0
}

post_upgrade() {
  if (( $(vercmp $2 0.32.0-2) < 0 )); then
    dconf update
  fi
}

# vim:set sw=2 et:

post_install() {
  grep -qe '^/usr/bin/fish$' etc/shells || echo '/usr/bin/fish' >> etc/shells
  grep -qe '^/bin/fish$' etc/shells || echo '/bin/fish' >> etc/shells
}

post_upgrade() {
  post_install
}

pre_remove() {
  sed -ri -e '\|^/usr/bin/fish$|d' -e '\|^/bin/fish$|d' etc/shells
}

# vim:set ts=2 sw=2 et:

post_upgrade() {
  if findmnt --fstab -uno SOURCE /boot &>/dev/null && ! mountpoint -q /boot; then
    echo "WARNING: /boot appears to be a separate partition but is not mounted."
  fi
}

post_remove() {
  rm -f boot/initramfs-linux.img
  rm -f boot/initramfs-linux-fallback.img
}

_global_units() {
    local unit=p11-kit-server.socket dir=/etc/systemd/user/sockets.target.wants

    case $1 in
        enable)
            mkdir -p $dir
            ln -sf /usr/lib/systemd/user/$unit $dir/$unit
            ;;
        disable)
            rm -f $dir/$unit
            rmdir -p --ignore-fail-on-non-empty $dir
            ;;
    esac
}

post_install() {
  # Enable socket by default
  _global_units enable
}

pre_remove() {
  _global_units disable
}

post_install() {
  # Enable socket by default
  systemctl --global enable pipewire.socket
}

post_upgrade() {
  if (( $(vercmp "$2" 0.1.6-2) < 0 )); then
    systemctl --global enable pipewire.socket
  fi
}

pre_remove() {
  systemctl --global disable pipewire.socket
}

