#!/bin/sh

post_install() {
	grep -qe '^/bin/zsh$' etc/shells || echo '/bin/zsh' >> etc/shells
	grep -qe '^/usr/bin/zsh$' etc/shells || echo '/usr/bin/zsh' >> etc/shells
